const cssBlock = (selector) => {
  const lineStartNeedle = `\n${selector} {`;
  const lineStart = cssRaw.indexOf(lineStartNeedle);
  const start = lineStart >= 0 ? lineStart + 1 : cssRaw.indexOf(`${selector} {`);
  if (start < 0) {
    return whitespaceTolerantCss("");
  }
  const end = cssRaw.indexOf("\n}", start);
  return whitespaceTolerantCss(end < 0 ? "" : cssRaw.slice(start, end + 2));
};
const cssBlockAfter = (selector, offset) => {
  const scopedCss = cssRaw.slice(Math.max(0, offset));
  const lineStartNeedle = `\n${selector} {`;
  const lineStart = scopedCss.indexOf(lineStartNeedle);
  const scopedStart = lineStart >= 0 ? lineStart + 1 : scopedCss.indexOf(`${selector} {`);
  if (scopedStart < 0) {
    return whitespaceTolerantCss("");
  }
  const start = Math.max(0, offset) + scopedStart;
  const end = cssRaw.indexOf("\n}", start);
  return whitespaceTolerantCss(end < 0 ? "" : cssRaw.slice(start, end + 2));
};
