// Position-dependent checks. Unlike the `includes` checks, these care where
// things sit relative to each other, and concatenation only preserves order
// *within* a file. They form three self-contained anchor groups:
//
//   1. nt-mail-adaptive          -> mail-list-toolbar, list-pane
//   2. nt-reading-pane           -> proton-message-header, header-navigation,
//                                   message-body-wrap
//   3. nt-compose-schedule-popover -> the fixed 1800-char window below it
//
// An anchor group may move into a component file as a whole. Splitting one
// across files breaks it, and breaks it *silently*: `indexOf` returns -1 and the
// guarded expressions below fall back to -1, so a check can keep passing while
// verifying nothing. After moving any of this JSX, deliberately break it once to
// confirm the check still fails.
//
// The list-pane anchor occurs twice because the compact and expanded mail
// renderings share the same section class. The check below asserts that expected
// count before using the first occurrence after the adaptive layout anchor, so a
// removed or duplicated pane cannot silently retarget the ordering check.
const mailAdaptiveRenderIndex = app.indexOf('className={`nt-mail-adaptive ${');
const mailListPaneAnchor = '<section className="nt-list-pane">';
const mailListPaneAnchorCount = app.split(mailListPaneAnchor).length - 1;
const mailToolbarRenderIndex =
  mailAdaptiveRenderIndex >= 0
    ? app.indexOf('className="nt-mail-list-toolbar"', mailAdaptiveRenderIndex)
    : -1;
const mailListPaneRenderIndex =
  mailAdaptiveRenderIndex >= 0
    ? app.indexOf('<section className="nt-list-pane">', mailAdaptiveRenderIndex)
    : -1;
const readingPaneRenderIndex = app.indexOf('<article className="nt-reading-pane">');
const protonMessageHeaderRenderIndex =
  readingPaneRenderIndex >= 0
    ? app.indexOf('<header className="nt-proton-message-header">', readingPaneRenderIndex)
    : -1;
const protonHeaderNavigationRenderIndex =
  readingPaneRenderIndex >= 0
    ? app.indexOf('className="nt-proton-header-navigation"', readingPaneRenderIndex)
    : -1;
const protonMessageBodyWrapRenderIndex =
  readingPaneRenderIndex >= 0
    ? app.indexOf('className="nt-proton-message-body-wrap"', readingPaneRenderIndex)
    : -1;
const composeSchedulePopoverRenderIndex = app.indexOf('className="nt-compose-schedule-popover"');
const composeSchedulePopoverRenderBlock =
  composeSchedulePopoverRenderIndex >= 0
    ? app.slice(composeSchedulePopoverRenderIndex, composeSchedulePopoverRenderIndex + 1800)
    : "";

