const composeColorSwatchesMatchProton = (() => {
  const match = composeData.match(/const COMPOSE_COLOR_SWATCHES = \[([\s\S]*?)\];/);
  if (!match) {
    return false;
  }

  const actual = [...match[1].matchAll(/"#[0-9A-Fa-f]{6}"/g)].map(([color]) => color.slice(1, -1));
  return JSON.stringify(actual) === JSON.stringify(PROTON_EDITOR_COLOR_SWATCHES);
})();

